questions.answer:
export function safeRedirect(url) {
  try {
    const base = "https://app.example.com";
    const target = new URL(url, base);
    if (target.origin !== base) return "/";
    if (target.protocol !== "https:" && target.protocol !== "http:") return "/";
    return target.pathname + target.search + target.hash;
  } catch {
    return "/";
  }
}

console.log(safeRedirect("/orders"));                 // /orders
console.log(safeRedirect("https://evil.example"));    // /
console.log(safeRedirect("javascript:alert(1)"));     // /

new URL(url, base) resolves relative paths and parses absolute ones, so you can compare origins instead of string-matching. javascript: parses with origin "null", which fails the origin check; a protocol allowlist is a second guard. Return only pathname + search + hash, never the raw input, so a crafted value cannot smuggle a scheme. Catch malformed URLs and default to a safe route.

